package com.ruoyi.paismart.application.intelligence;
import com.ruoyi.paismart.application.MembershipService;
import com.ruoyi.paismart.application.documents.DocumentService;
import com.ruoyi.paismart.application.spaces.SpaceService;
import com.ruoyi.paismart.infrastructure.intelligence.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.test.util.ReflectionTestUtils;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class SearchBoundaryTest {
    JdbcTemplate db;SearchService search;DocumentService docs;SpaceService spaces;ControlledHttp http;ModelGateway models;
    @BeforeEach void prepare(){db=new JdbcTemplate(new DriverManagerDataSource("jdbc:h2:mem:search_"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1"));db.execute("CREATE TABLE ps_document(id VARCHAR(40) PRIMARY KEY,user_id BIGINT,space_id VARCHAR(40),visibility VARCHAR(30),version INT,status VARCHAR(20),deleted_at TIMESTAMP,updated_at TIMESTAMP)");db.execute("CREATE TABLE ps_document_chunk(id VARCHAR(40),document_id VARCHAR(40),content_version INT)");docs=mock(DocumentService.class);spaces=mock(SpaceService.class);http=mock(ControlledHttp.class);models=mock(ModelGateway.class);when(spaces.visibleSpaceIds(any())).thenReturn(Set.of("org1"));search=new SearchService(db,http,mock(IntelligenceSettings.class),mock(ProviderService.class),models,spaces,docs);ReflectionTestUtils.setField(search,"members",mock(MembershipService.class));}
    void doc(String id,long user,String space,String visibility){db.update("INSERT INTO ps_document VALUES(?,?,?,?,1,'READY',NULL,TIMESTAMP '2026-10-01 10:00:00')",id,user,space,visibility);db.update("INSERT INTO ps_document_chunk VALUES(?,?,1)",id,id);db.update("INSERT INTO ps_document_chunk VALUES(?,?,0)",id+"old",id);}
    @Test void statisticsCountAllVisibleCurrentChunksBeyondOneHundredDocuments(){for(int i=0;i<150;i++)doc("own"+i,2,null,"PRIVATE");doc("other",3,null,"PRIVATE");doc("public",3,null,"PUBLIC");doc("org",3,"org1","ORGANIZATION");doc("unrelated",3,"org2","ORGANIZATION");var result=search.statistics(new SpaceService.Scope(2,false));assertEquals(152L,result.get("visibleDocuments"));assertEquals(152L,result.get("countedChunks"));assertEquals(true,result.get("chunkCountComplete"));verifyNoInteractions(http,models);}
    @Test void organizationConversationStatisticsExcludePrivateDocumentCounts(){doc("private",2,"org1","PRIVATE");doc("org",3,"org1","ORGANIZATION");doc("public",3,"org1","PUBLIC");assertEquals(2L,search.statistics(new SpaceService.Scope(2,false),"org1").get("visibleDocuments"));}
    @Test void organizationConversationCannotCarryPrivateOrOtherSpaceEvidence(){var privateDoc=mock(DocumentService.Document.class);when(privateDoc.spaceId()).thenReturn("org1");when(privateDoc.visibility()).thenReturn("PRIVATE");var publicDoc=mock(DocumentService.Document.class);when(publicDoc.spaceId()).thenReturn("org1");when(publicDoc.visibility()).thenReturn("PUBLIC");when(docs.getReadable(any(),eq("private"))).thenReturn(privateDoc);when(docs.getReadable(any(),eq("public"))).thenReturn(publicDoc);var evidence=List.of(new SearchService.Evidence("privateChunk","private",1,0,null,"私有","私人文本","","",1,"RRF"),new SearchService.Evidence("publicChunk","public",1,0,null,"公共","公共文本","","",1,"RRF"));var result=search.sharedEvidence(new SpaceService.Scope(2,false),evidence,"org1");assertEquals(1,result.size());assertEquals("publicChunk",result.get(0).id());}
    @Test void latestUpdateUsesTheSameVisibleScopeAndCannotRevealPrivateDocumentActivity(){doc("visible",3,null,"PUBLIC");doc("hidden",3,null,"PRIVATE");db.update("UPDATE ps_document SET updated_at=TIMESTAMP '2026-10-02 11:00:00' WHERE id='visible'");db.update("UPDATE ps_document SET updated_at=TIMESTAMP '2026-10-03 15:00:00' WHERE id='hidden'");var result=search.statistics(new SpaceService.Scope(2,false));assertEquals(java.time.LocalDateTime.of(2026,10,2,11,0),result.get("latestUpdatedAt"));assertEquals("PAISMART_MYSQL",result.get("authority"));assertEquals("CURRENT_PERMISSION_SCOPE",result.get("source"));assertFalse(result.containsKey("storeSizeInBytes"));assertFalse(result.containsKey("deletedFragmentCount"));verifyNoInteractions(http,models);}
    @Test void emptyVisibleScopeReportsNoLatestUpdateRatherThanInventingAnEsFact(){var result=search.statistics(new SpaceService.Scope(2,false));assertEquals(0L,result.get("visibleDocuments"));assertNull(result.get("latestUpdatedAt"));assertEquals("PAISMART_MYSQL",result.get("authority"));verifyNoInteractions(http,models);}
}
